import json

def encode_cursor(record):
    return json.dumps([record["created"], record["id"]])

def is_after_cursor(record, cursor):
    if cursor is None:
        return True
    created, identity = json.loads(cursor)
    return (record["created"], record["id"]) < (created, identity)

